mapper.update:
UPDATE campus_ingest_run_log
SET detection_trigger_count = #{detectionTriggerCount},
    detection_hit_count = #{detectionHitCount},
    detection_alert_count = #{detectionAlertCount},
    detection_error_message = #{detectionErrorMessage}
WHERE run_id = #{runId}

mapper.select:
SELECT id, run_id, task_id, run_status, trigger_type, start_time, end_time,
       duration_ms, fetched_count, success_count, duplicate_count, invalid_count,
       detection_trigger_count, detection_hit_count, detection_alert_count, detection_error_message,
       fail_count, error_message,
       error_type, retry_count, scheduler_node, create_user_id, create_time
FROM campus_ingest_run_log


        AND task_id = #{taskId}


        AND run_status = #{runStatus}


        AND error_type = #{errorType}


        AND trigger_type = #{triggerType}


ORDER BY id DESC

mapper.delete:
DELETE FROM campus_ingest_run_log
WHERE create_time < #{expireBefore}
  AND run_status != 'running'
ORDER BY id ASC
LIMIT #{limit}
